def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    rich_pressure = 0
    urgent_opponents = 0

    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if bid >= 120:
                    rich_pressure += 1
            if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 10) <= 3:
                urgent_opponents += 1

    if not alive:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (supply - WATER_REQ) / float(MAX_SUPPLY - WATER_REQ)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    danger = 0
    if hp <= 2:
        danger += 2
    elif hp <= 4:
        danger += 1
    if no_water_days >= 2:
        danger += 3
    elif no_water_days >= 1:
        danger += 1
    if supply <= 17:
        danger += 1

    if danger >= 4:
        bid = 92.0
        if highest_prev > 0 and highest_prev < 110:
            bid = max(bid, highest_prev + 3.0)
        return float(min(budget, bid))

    if danger >= 2:
        bid = 48.0
        if highest_prev <= 95 and highest_prev > 0:
            bid = max(bid, highest_prev + 2.0)
        if rich_pressure >= 2:
            bid -= 6.0
        if supply <= 17:
            bid += 8.0
        return float(min(budget, max(20.0, bid)))

    base = 24.0 + (1.0 - scarcity) * 10.0
    if avg_prev > 0 and avg_prev < 80:
        base = max(base, avg_prev + 1.5)
    if highest_prev >= 120:
        base = min(base, 34.0)
    if rich_pressure >= 2:
        base -= 4.0
    if urgent_opponents >= 2:
        base += 5.0
    if day >= 8 and hp >= 6:
        base -= 3.0

    reserve_target = DAILY_SALARY * max(0, 10 - int(day)) * 0.18
    affordable = budget - reserve_target
    if affordable < 8.0:
        affordable = min(budget, 8.0)

    bid = min(base, affordable)
    bid = max(6.0, bid)
    return float(min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', MIN_SUPPLY))
    day = day_context.get('day', 0)

    budget = float(my_status.get('budget', 0.0))
    hp = float(my_status.get('hp', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return min(budget, DAILY_SALARY * 0.4)

    # Immediate reaction from yesterday trace only
    prev_bids = []
    prev_hp_after = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        if prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev.get('bid')))
            except Exception:
                pass
        if prev.get('hp_after') is not None:
            try:
                prev_hp_after.append(float(prev.get('hp_after')))
            except Exception:
                pass

    # Estimate how competitive the market was yesterday
    if prev_bids:
        highest_prev_bid = max(prev_bids)
        second_prev_bid = sorted(prev_bids)[-2] if len(prev_bids) >= 2 else highest_prev_bid
    else:
        highest_prev_bid = DAILY_SALARY * 0.6
        second_prev_bid = highest_prev_bid

    # Supply pressure: if supply is tight, winning water is more valuable.
    # Convert supply to expected number of water units relative to requirement.
    # (We only use this for scaling; actual allocation is handled by the game.)
    supply_ratio = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY != MIN_SUPPLY else 0.5
    supply_ratio = max(0.0, min(1.0, supply_ratio))

    # Base bid: target just above mid-competitor when supply is tight.
    # If supply is ample, undercut to save budget.
    if supply_ratio < 0.35:
        target = second_prev_bid + 3.0
    elif supply_ratio < 0.7:
        target = (second_prev_bid + highest_prev_bid) / 2.0
    else:
        target = second_prev_bid - 2.0

    # Survival urgency adjustments
    # If my hp is low or I've already gone without water, I must bid more.
    if hp <= 2.0 or no_water_days >= 2:
        urgency = 1.0
    elif hp <= 4.0 or no_water_days == 1:
        urgency = 0.75
    else:
        urgency = 0.55

    # If yesterday saw very aggressive bids, slightly increase to avoid losing.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        market_factor = 0.85
    else:
        market_factor = 0.7

    bid = target * (market_factor + urgency * 0.35)

    # Clamp to reasonable range relative to budget
    # Ensure we don't exceed budget and avoid bidding near zero when alive.
    min_reasonable = DAILY_SALARY * (0.25 if hp > 4 else 0.6)
    bid = max(min_reasonable, bid)
    bid = min(bid, budget)

    # If budget is extremely low, still bid enough to have a chance.
    if budget < DAILY_SALARY * 0.3:
        bid = min(budget, DAILY_SALARY * 0.5)

    # Final safety clamp
    if bid < 0.0:
        bid = 0.0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if not alive_opponents:
        return 10.0

    avg_prev = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 70.0
    max_prev = max(yesterday_bids) if yesterday_bids else 80.0

    if my_status['hp'] <= 3:
        return min(my_status['budget'], max_prev + 5.0)

    if supply < WATER_REQ * 2:
        return min(my_status['budget'], max(avg_prev, 75.0))

    return min(my_status['budget'], max(avg_prev * 0.8, 40.0))
